import React from 'react';

const PropertyCard = ({ prop, isFav, isComparing, isCompact, onViewDetails, onShow360, onShowMap, toggleFavorite, toggleCompare, onScheduleVisit, handlePrint, shareProperty, copyDetails, onOpenCalculator, handleEditProperty, handleDeleteProperty, adminInfo }) => {
    // Investment Logic
    const ppm = prop.price && prop.area ? prop.price / prop.area : 0;
    let badge = null;
    if (ppm > 0) {
        if (ppm < 12000) badge = <span className="badge bg-danger position-absolute top-0 start-0 m-2 shadow px-3 py-2" style={{zIndex:2}}>🔥 لقطة</span>;
        else if (ppm > 30000) badge = <span className="badge bg-warning text-dark position-absolute top-0 start-0 m-2 shadow px-3 py-2" style={{zIndex:2}}>💎 فاخر</span>;
        else badge = <span className="badge bg-info text-dark position-absolute top-0 start-0 m-2 shadow px-3 py-2" style={{zIndex:2}}>✨ مميز</span>;
    }

    const isSold = prop.availability === 'مباعة';

    return (
        <div className={`card h-100 shadow-sm ${isSold ? 'border-secondary' : ''}`} style={isSold ? { opacity: 0.85, backgroundColor: '#f8f9fa' } : {}}>
            <div className="position-relative">
                {badge}
                {isSold && (
                    <div className="position-absolute top-50 start-50 translate-middle badge bg-danger fs-5 shadow" style={{zIndex: 5, transform: 'translate(-50%, -50%) rotate(-15deg)', opacity: 0.95, border: '2px solid white'}}>
                        🚫 تم البيع
                    </div>
                )}
                <img src={(prop.images && prop.images[0]) || prop.imageUrl} className="card-img-top" alt={`صورة لـ ${prop.type}`} style={{cursor: 'pointer', height: isCompact ? '140px' : '220px', objectFit: 'cover', borderTopLeftRadius: '20px', borderTopRightRadius: '20px', filter: isSold ? 'grayscale(100%)' : 'none'}} onClick={() => onViewDetails && onViewDetails(prop)} />
                <div className="position-absolute" style={{top:10,right:10}}>
                    <span className={`badge bg-primary fw-bold ${isCompact ? 'small' : ''}`}>{prop.price?.toLocaleString?.() ?? prop.price} ج</span>
                </div>
            </div>
            <div className={`card-body d-flex flex-column ${isCompact ? 'p-2' : ''}`}>
                <h5 className={`card-title ${isCompact ? 'fs-6 mb-1' : ''}`}>{prop.type} {prop.status} في {prop.location?.neighborhood || prop.location?.city}</h5>
                {!isCompact && <p className="card-text text-muted small flex-grow-1" style={{ display: '-webkit-box', WebkitLineClamp: 3, WebkitBoxOrient: 'vertical', overflow: 'hidden', whiteSpace: 'pre-line' }}>{prop.description}</p>}
                <ul className="list-group list-group-flush mt-auto" style={{background: 'transparent'}}>
                    <li className={`list-group-item px-0 ${isCompact ? 'py-1 small' : ''}`} style={{background: 'transparent'}}>📏 المساحة: {prop.area} م²</li>
                    <li className={`list-group-item px-0 ${isCompact ? 'py-1 small' : ''}`} style={{background: 'transparent'}}>�️ الغرف: {prop.rooms} | 🛁 الحمامات: {prop.bathrooms}</li>
                </ul>
            </div>
            <div className={`card-footer d-flex justify-content-between align-items-center ${isCompact ? 'p-1' : ''}`} style={{background: 'rgba(255,255,255,0.05)'}}>
                <small className={prop.availability === 'متاحة' ? 'text-success fw-bold' : (isSold ? 'text-danger fw-bold' : 'text-warning fw-bold')}>
                    {prop.availability === 'متاحة' ? '✅ متاح' : (isSold ? '🚫 مباعة' : '❌ محجوزة')}
                </small>
                <div className="d-flex align-items-center">
                    <button type="button" className={`btn btn-sm me-1 shadow-sm ${isFav ? 'btn-danger' : 'btn-light text-danger'}`} onClick={() => toggleFavorite(prop.id)} title={isFav ? "إزالة من المفضلة" : "إضافة للمفضلة"}>{isFav ? '❤️' : '🤍'}</button>
                    <button type="button" className="btn btn-sm btn-light text-primary me-2 shadow-sm" onClick={() => onViewDetails && onViewDetails(prop)} title="تفاصيل كاملة">🔍</button>
                    
                    <div className="dropdown">
                        <button className="btn btn-sm btn-outline-secondary dropdown-toggle" type="button" id={`dropdownMenuButton-${prop.id}`} data-bs-toggle="dropdown" aria-expanded="false">
                            ...
                        </button>
                        <ul className="dropdown-menu dropdown-menu-end" aria-labelledby={`dropdownMenuButton-${prop.id}`}>
                            <li><button className="dropdown-item" onClick={() => onScheduleVisit(prop)}>📅 حجز زيارة</button></li>
                            <li><button className="dropdown-item" onClick={() => toggleCompare(prop.id)}>⚖️ {isComparing ? 'إزالة من المقارنة' : 'إضافة للمقارنة'}</button></li>
                            <li><button className="dropdown-item" onClick={() => onShowMap && onShowMap(prop)}>🗺️ عرض على الخريطة</button></li>
                            {prop.threeSixtyUrl && <li><button className="dropdown-item" onClick={() => onShow360(prop.threeSixtyUrl)}>🔄 جولة 360°</button></li>}
                            <li><hr className="dropdown-divider" /></li>
                            <li><button className="dropdown-item" onClick={() => shareProperty(prop)}>📱 مشاركة واتساب</button></li>
                            <li><button className="dropdown-item" onClick={() => {
                                const url = window.location.href;
                                window.open(`https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}`, '_blank');
                            }}>📘 مشاركة فيسبوك</button></li>
                            <li><button className="dropdown-item" onClick={() => {
                                const text = `فرصة عقارية مميزة! 🏠\n${prop.type} ${prop.status} في ${prop.location?.city || ''}\nالسعر: ${prop.price?.toLocaleString()} جنيه\n\n#عقارات #سمسار`;
                                window.open(`https://twitter.com/intent/tweet?text=${encodeURIComponent(text)}`, '_blank');
                            }}>🐦 مشاركة تويتر</button></li>
                            <li><button className="dropdown-item" onClick={() => copyDetails(prop)}>📋 نسخ التفاصيل</button></li>
                            <li><button className="dropdown-item" onClick={() => handlePrint(prop)}>🖨️ طباعة</button></li>
                            <li><button className="dropdown-item" onClick={() => onOpenCalculator(prop.price)}>🧮 حساب القسط</button></li>
                            <li><hr className="dropdown-divider" /></li>
                            {adminInfo && (
                                <li><button className="dropdown-item text-info" data-bs-toggle="modal" data-bs-target="#newPropertyModal" onClick={() => { handleEditProperty(prop) }}>✏️ تعديل</button></li>
                            )}
                            {adminInfo && adminInfo.role === 'admin' && (
                                <li><button className="dropdown-item text-danger" onClick={() => handleDeleteProperty(prop.id, `${prop.type} في ${prop.location?.city || ''}`)}>🗑️ حذف</button></li>
                            )}
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default PropertyCard;
